package org.dromara.ai.workspace;

import lombok.RequiredArgsConstructor;
import org.dromara.common.json.utils.JsonUtils;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.*;

@Service
@org.springframework.scheduling.annotation.EnableScheduling
@RequiredArgsConstructor
public class WorkspaceKnowledgeJobs {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final WorkspaceFileStore files;private final WorkspaceKnowledgeDocumentExtractor extractor;private volatile boolean ready;
 @EventListener(ApplicationReadyEvent.class) public void recover(){jdbc.update("UPDATE ai_knowledge_job SET status='QUEUED',error_code='RecoveredAfterRestart' WHERE status='RUNNING'");jdbc.update("UPDATE ai_knowledge_document_version v SET status='QUEUED' WHERE status='INDEXING' AND EXISTS(SELECT 1 FROM ai_knowledge_job j WHERE j.document_id=v.document_id AND j.version=v.version AND j.status='QUEUED')");ready=true;}
 @Scheduled(fixedDelay=1000) public void work(){if(!ready)return;var job=tx.execute(status->{var rows=jdbc.queryForList("SELECT * FROM ai_knowledge_job WHERE status='QUEUED' ORDER BY created_at LIMIT 1 FOR UPDATE SKIP LOCKED");if(rows.isEmpty())return null;var j=rows.getFirst();jdbc.update("UPDATE ai_knowledge_job SET status='RUNNING',error_code=NULL WHERE id=?",j.get("id"));jdbc.update("UPDATE ai_knowledge_document_version SET status=CASE WHEN status='READY' THEN status ELSE 'INDEXING' END WHERE document_id=? AND version=?",j.get("document_id"),j.get("version"));return j;});if(job==null)return;
  try{
   UUID doc=(UUID)job.get("document_id");int version=((Number)job.get("version")).intValue();var source=jdbc.queryForList("SELECT v.file_id,v.text_content,v.content_hash,v.source_media_type,v.extraction_method,f.filename FROM ai_knowledge_document d JOIN ai_knowledge_document_version v ON v.document_id=d.id JOIN ai_file f ON f.id=v.file_id WHERE d.id=? AND v.version=? AND d.deleted_at IS NULL AND f.deleted_at IS NULL",doc,version);if(source.isEmpty()){cancel(job);return;}var sourceRow=source.getFirst();WorkspaceKnowledgeDocumentExtractor.Extraction extraction;if("LEGACY_TEXT".equals(sourceRow.get("extraction_method")))extraction=new WorkspaceKnowledgeDocumentExtractor.Extraction(sourceRow.get("source_media_type").toString(),"LEGACY_TEXT",List.of(new WorkspaceKnowledgeDocumentExtractor.Section("LINE","全文",sourceRow.get("text_content").toString())),Map.of("migrated",true));else{var file=files.row((UUID)sourceRow.get("file_id"));extraction=extractor.extract(sourceRow.get("filename").toString(),files.bytes(file));}String fullText=extraction.fullText(),hash=WorkspaceTools.hash(fullText);
   tx.executeWithoutResult(status->{var rows=jdbc.queryForList("SELECT d.deleted_at,v.text_content,v.content_hash,v.extraction_method FROM ai_knowledge_document d JOIN ai_knowledge_document_version v ON v.document_id=d.id WHERE d.id=? AND v.version=? FOR UPDATE OF d,v",doc,version);if(rows.isEmpty()||rows.getFirst().get("deleted_at")!=null){jdbc.update("UPDATE ai_knowledge_job SET status='CANCELLED',finished_at=NOW() WHERE id=?",job.get("id"));return;}var versionRow=rows.getFirst();if("PENDING".equals(versionRow.get("extraction_method"))){jdbc.update("UPDATE ai_knowledge_document_version SET text_content=?,content_hash=?,source_media_type=?,extraction_method=?,extraction_metadata=?::jsonb,status='INDEXING' WHERE document_id=? AND version=?",fullText,hash,extraction.mediaType(),extraction.method(),JsonUtils.toJsonString(extraction.metadata()),doc,version);}else if(!"LEGACY_TEXT".equals(versionRow.get("extraction_method"))&&!hash.equals(versionRow.get("content_hash")))throw new WorkspaceDenied(409,"ReindexContentChanged");
    jdbc.update("DELETE FROM ai_knowledge_index WHERE document_id=? AND version=?",doc,version);int chunk=0;for(var section:extraction.sections())chunk=putSection(doc,version,chunk,section);jdbc.update("UPDATE ai_knowledge_document_version SET status='READY' WHERE document_id=? AND version=?",doc,version);jdbc.update("UPDATE ai_knowledge_document SET indexed_version=GREATEST(COALESCE(indexed_version,0),?),updated_at=NOW() WHERE id=?",version,doc);jdbc.update("UPDATE ai_knowledge_job SET status='COMPLETED',finished_at=NOW() WHERE id=?",job.get("id"));
   });
  }catch(Exception e){String code=e instanceof WorkspaceDenied?e.getMessage():"IndexingFailed";jdbc.update("UPDATE ai_knowledge_job SET status='FAILED',error_code=?,finished_at=NOW() WHERE id=?",code,job.get("id"));jdbc.update("UPDATE ai_knowledge_document_version SET status=CASE WHEN status='READY' THEN status ELSE 'ERROR' END WHERE document_id=? AND version=?",job.get("document_id"),job.get("version"));}
 }
 private void cancel(Map<String,Object> job){jdbc.update("UPDATE ai_knowledge_job SET status='CANCELLED',finished_at=NOW() WHERE id=?",job.get("id"));}
 private int putSection(UUID doc,int version,int chunk,WorkspaceKnowledgeDocumentExtractor.Section section){String[] lines=section.text().split("\\n",-1);StringBuilder buffer=new StringBuilder();int start=1;for(int index=0;index<lines.length;index++){String line=lines[index];int number=index+1;if(buffer.length()+line.length()+1>1200&&!buffer.isEmpty()){put(doc,version,chunk++,start,number-1,section,buffer.toString());buffer.setLength(0);start=number;}if(line.length()>1200){if(!buffer.isEmpty()){put(doc,version,chunk++,start,number-1,section,buffer.toString());buffer.setLength(0);}for(int offset=0;offset<line.length();offset+=1000)put(doc,version,chunk++,number,number,section,line.substring(offset,Math.min(line.length(),offset+1200)));start=number+1;}else buffer.append(line).append('\n');}if(!buffer.isEmpty())put(doc,version,chunk++,start,lines.length,section,buffer.toString());return chunk;}
 private void put(UUID doc,int version,int chunk,int start,int end,WorkspaceKnowledgeDocumentExtractor.Section section,String content){jdbc.update("INSERT INTO ai_knowledge_index(document_id,version,chunk_index,line_start,line_end,location_type,location_label,content) VALUES(?,?,?,?,?,?,?,?)",doc,version,chunk,start,end,section.locationType(),section.locationLabel(),content);}
}
